#include "EEPROM24CXX.h"
namespace EEPROM24CXX_Internal {
uint8_t deviceAddress=0x50,writeProtectPin=255;uint32_t memorySize=256;uint16_t pageSize=8;bool address16Bit=false,blockAddressing=false,cm01=false;uint32_t cursor=0;
bool checkAddress(uint32_t a,uint32_t n){return n&&a<memorySize&&n<=memorySize-a;}
uint8_t getDeviceAddress(uint32_t a){uint8_t d=deviceAddress;if(cm01)d|=((a>>16)&1)<<1;else if(blockAddressing)d|=(a>>8)&7;return d;}
bool waitReady(uint8_t d,uint32_t t){uint32_t s=millis();do{Wire.beginTransmission(d);if(Wire.endTransmission()==0)return true;delay(1);}while(millis()-s<t);return false;}
bool writeByteRaw(uint32_t a,uint8_t v){if(!checkAddress(a))return false;uint8_t d=getDeviceAddress(a);Wire.beginTransmission(d);if(address16Bit){Wire.write((a>>8)&255);Wire.write(a&255);}else Wire.write(a&255);Wire.write(v);if(Wire.endTransmission()!=0)return false;return waitReady(d);}
uint8_t readByteRaw(uint32_t a){if(!checkAddress(a))return 255;uint8_t d=getDeviceAddress(a);Wire.beginTransmission(d);if(address16Bit){Wire.write((a>>8)&255);Wire.write(a&255);}else Wire.write(a&255);if(Wire.endTransmission()!=0)return 255;uint8_t n=Wire.requestFrom(d,(uint8_t)1);if(n!=1||!Wire.available())return 255;return Wire.read();}
bool writePage(uint32_t a,const uint8_t*b,uint16_t n){if(!b||!checkAddress(a,n)||n>pageSize||((a%pageSize)+n)>pageSize)return false;uint8_t d=getDeviceAddress(a);Wire.beginTransmission(d);if(address16Bit){Wire.write((a>>8)&255);Wire.write(a&255);}else Wire.write(a&255);for(uint16_t i=0;i<n;i++)Wire.write(b[i]);if(Wire.endTransmission()!=0)return false;return waitReady(d);}
}
bool EEPROM24CXX_Internal::initialized=false;
void mem_init(EEPROMType t,uint8_t addr,uint8_t wp,uint8_t led,bool useLed){Wire.begin();EEPROM24CXX_Internal::deviceAddress=addr;EEPROM24CXX_Internal::writeProtectPin=wp;EEPROM24CXX_Internal::cursor=0;EEPROM24CXX_Internal::initialized=false;EEPROM24CXX_Internal::cm01=false;EEPROM24CXX_Internal::blockAddressing=false;EEPROM24CXX_Internal::address16Bit=false;
switch(t){case C24C01:EEPROM24CXX_Internal::memorySize=128;EEPROM24CXX_Internal::pageSize=8;break;case C24C02:EEPROM24CXX_Internal::memorySize=256;EEPROM24CXX_Internal::pageSize=8;break;case C24C04:EEPROM24CXX_Internal::memorySize=512;EEPROM24CXX_Internal::pageSize=16;EEPROM24CXX_Internal::blockAddressing=true;break;case C24C08:EEPROM24CXX_Internal::memorySize=1024;EEPROM24CXX_Internal::pageSize=16;EEPROM24CXX_Internal::blockAddressing=true;break;case C24C16:EEPROM24CXX_Internal::memorySize=2048;EEPROM24CXX_Internal::pageSize=16;EEPROM24CXX_Internal::blockAddressing=true;break;case C24C32:EEPROM24CXX_Internal::memorySize=4096;EEPROM24CXX_Internal::pageSize=32;EEPROM24CXX_Internal::address16Bit=true;break;case C24C64:EEPROM24CXX_Internal::memorySize=8192;EEPROM24CXX_Internal::pageSize=32;EEPROM24CXX_Internal::address16Bit=true;break;case C24C128:EEPROM24CXX_Internal::memorySize=16384;EEPROM24CXX_Internal::pageSize=64;EEPROM24CXX_Internal::address16Bit=true;break;case C24C256:EEPROM24CXX_Internal::memorySize=32768;EEPROM24CXX_Internal::pageSize=64;EEPROM24CXX_Internal::address16Bit=true;break;case C24C512:EEPROM24CXX_Internal::memorySize=65536;EEPROM24CXX_Internal::pageSize=128;EEPROM24CXX_Internal::address16Bit=true;break;case C24CM01:EEPROM24CXX_Internal::memorySize=131072;EEPROM24CXX_Internal::pageSize=256;EEPROM24CXX_Internal::address16Bit=true;EEPROM24CXX_Internal::cm01=true;break;default:EEPROM24CXX_Internal::memorySize=0;return;}
if(wp!=255){pinMode(wp,OUTPUT);digitalWrite(wp,LOW);}if(useLed)pinMode(led,OUTPUT);Wire.beginTransmission(addr);EEPROM24CXX_Internal::initialized=Wire.endTransmission()==0;if(useLed)digitalWrite(led,EEPROM24CXX_Internal::initialized?HIGH:LOW);}
bool writeByte(uint32_t a,uint8_t v){return EEPROM24CXX_Internal::writeByteRaw(a,v);}uint8_t readByte(uint32_t a){return EEPROM24CXX_Internal::readByteRaw(a);}bool updateByte(uint32_t a,uint8_t v){return EEPROM24CXX_Internal::checkAddress(a)&&(readByte(a)==v||writeByte(a,v));}
void lock_mem(){if(EEPROM24CXX_Internal::writeProtectPin!=255)digitalWrite(EEPROM24CXX_Internal::writeProtectPin,HIGH);}void unlock_mem(){if(EEPROM24CXX_Internal::writeProtectPin!=255)digitalWrite(EEPROM24CXX_Internal::writeProtectPin,LOW);}
void mem_seek(uint32_t a){if(a<=size())EEPROM24CXX_Internal::cursor=a;}void rewind(){mem_seek(0);}void skip(uint32_t n){uint32_t c=position();if(n<=size()-c)mem_seek(c+n);}void mem_back(uint32_t n){uint32_t c=position();mem_seek(n>c?0:c-n);}void mem_end(){mem_seek(size());}
uint32_t position(){return EEPROM24CXX_Internal::cursor;}uint32_t mem_remaining(){return size()-position();}bool available(uint32_t n){return n<=mem_remaining();}uint8_t peek(){return available()?readByte(position()):255;}
uint32_t size(){return EEPROM24CXX_Internal::memorySize;}uint16_t pageSize(){return EEPROM24CXX_Internal::pageSize;}bool is16Bit(){return EEPROM24CXX_Internal::address16Bit;}bool usesBlockAddress(){return EEPROM24CXX_Internal::blockAddressing;}
bool w_bytes(const uint8_t*b,uint32_t n){if(!b||!available(n))return false;for(uint32_t i=0;i<n;i++){if(!writeByte(position(),b[i]))return false;mem_seek(position()+1);}return true;}
bool r_bytes(uint8_t*b,uint32_t n){if(!b||!available(n))return false;for(uint32_t i=0;i<n;i++){b[i]=readByte(position());mem_seek(position()+1);}return true;}
bool w_str(const String&s){if(!available((uint32_t)s.length()+1))return false;for(uint32_t i=0;i<s.length();i++){if(!writeByte(position(),s[i]))return false;mem_seek(position()+1);}if(!writeByte(position(),0))return false;mem_seek(position()+1);return true;}
String r_str(){String s;while(available()){char c=readByte(position());mem_seek(position()+1);if(!c)break;s+=c;}return s;}
bool overwrite(uint32_t a,const String&s){if(!EEPROM24CXX_Internal::checkAddress(a,(uint32_t)s.length()+1))return false;for(uint32_t i=0;i<s.length();i++)if(!writeByte(a+i,s[i]))return false;return writeByte(a+s.length(),0);}
bool wipe(uint32_t a,uint32_t n){if(!EEPROM24CXX_Internal::checkAddress(a,n))return false;unlock_mem();bool ok=true;for(uint32_t i=0;i<n;i++)if(!writeByte(a+i,255)){ok=false;break;}lock_mem();return ok;}bool fill(uint32_t a,uint32_t n,uint8_t v){if(!EEPROM24CXX_Internal::checkAddress(a,n))return false;unlock_mem();bool ok=true;for(uint32_t i=0;i<n;i++)if(!writeByte(a+i,v)){ok=false;break;}lock_mem();return ok;}
bool compare(uint32_t a,uint32_t b,uint32_t n){if(!EEPROM24CXX_Internal::checkAddress(a,n)||!EEPROM24CXX_Internal::checkAddress(b,n))return false;for(uint32_t i=0;i<n;i++)if(readByte(a+i)!=readByte(b+i))return false;return true;}bool wipe_all(){bool ok=wipe(0,size());rewind();return ok;}
void read_all(){Serial.println(F("EEPROM dump"));for(uint32_t a=0;a<size();a++){if(a%16==0){Serial.println();Serial.print(a,HEX);Serial.print(F(": "));}uint8_t v=readByte(a);if(v<16)Serial.print('0');Serial.print(v,HEX);Serial.print(' ');}Serial.println();}
